import {stats,item,damage} from './core.js?v=26';
import {xpBase,advanceXP,mobReward,enchant,enchantPrice,enemyBudget} from './progression.js?v=26';
import {basicInterval,resolveStrike} from './combat.js?v=26';
import {KITS} from './skills.js?v=26';
import {SKILL_UNLOCK} from './skill-growth.js?v=26';
import {findPath} from './navigation.js?v=26';
import {allocate,rngFrom,vipState,applyVipReward,buyVip} from './bot-society.js?v=26';
import {premiumApply,premiumQuote} from './premium.js?v=26';
const log=(b,text)=>{b.journal||=[];b.journal.push(text);b.journal=b.journal.slice(-8);};
export function citizenStats(b){return b.cachedStats||(b.cachedStats=stats(b.player));}
function refresh(b){delete b.cachedStats;delete b.appearance;return citizenStats(b);}
function evolve(b,xp){const p=b.player,old=p.level;advanceXP(p,xp);if(p.level!==old){allocate(p);const st=refresh(b);p.hp=st.hp;p.mp=st.mp;log(b,'Alcancei o nível '+p.level+' e distribuí '+((p.level-old)*5)+' pontos.');}}
export function finishTask(b,{hunt=false,enemyLevel=b.player.level}={}){const p=b.player,rng=rngFrom(b.seed+(b.quests+b.kills)*103);if(hunt){const reward=mobReward(p,enemyLevel,false);p.killCount++;b.kills++;applyVipReward(p,reward);p.materials['Fragmento de Magícula']=(p.materials['Fragmento de Magícula']||0)+1;if(b.kills%3===0)p.shards++;evolve(b,reward.xp);log(b,'Caça Nv'+enemyLevel+': +'+reward.xp+' EXP e '+reward.gold+' ouro.');}else{const xp=Math.ceil(xpBase(p.level)*.18);p.gold+=30+p.level*3;b.quests++;evolve(b,xp);log(b,'Entreguei suprimentos: +'+xp+' EXP.');}
 if((b.kills+b.quests)%5===0){const slots=p.bag.map(i=>i.slot),slot=slots[(b.kills+b.quests)%slots.length],quality=p.level<25?'D':p.level<75?'B':p.level<175?'A':p.level<250?'SS+':'SSS',piece=item(p.classId,p.level,slot,quality,rng),old=p.bag.find(i=>i.id===p.equipped[slot]);if(!old||piece.level>old.level){p.bag=p.bag.filter(i=>i.slot!==slot);p.bag.push(piece);p.equipped[slot]=piece.id;b.loot++;refresh(b);log(b,'Equipei '+piece.name+' Nv'+piece.level+'.');}}
}
export function maintainBuild(b){const p=b.player,weapon=p.bag.find(i=>i.id===p.equipped.weapon);if(!weapon)return;const rng=rngFrom(b.seed+Math.floor(b.ageSeconds/1800));if(b.profile==='free'){const cost=enchantPrice(weapon.enchant);if(p.gold>=cost.gold&&p.shards>=cost.crystals){const out=enchant(p,weapon,rng);if(out.success)log(b,'Aprimorei a arma para +'+weapon.enchant+'.');}}else{const q=premiumQuote(p,'enchant',weapon);if(q.ok&&q.price<=p.wallet.cash){const out=premiumApply(p,'enchant',weapon,false,rng);if(out.ok){b.spent+=q.price;log(b,'Usei '+q.price+' cash numa tentativa de aprimoramento.');}}}refresh(b);}
function budget(b){const p=b.player,previous=Math.floor((b.ageSeconds||0)/86400);b.days=previous;const funded=Math.floor(b.fundedDays||0);if(previous>funded){const amount=(previous-funded)*(b.profile==='free'?0:b.profile==='vip'?10000:100000);p.wallet.cash+=amount;b.fundedDays=previous;if(amount)log(b,'Orçamento de '+(previous-funded)+' dia(s): +'+amount+' cash.');const wanted=b.profile==='vip'?1:b.profile==='patron'?2:0;if(wanted&&vipState(p).level<wanted)buyVip(p,wanted);}}
function age(b,dt){const before=Math.floor((b.ageSeconds||0)/1800);b.ageSeconds=(b.ageSeconds||0)+dt;budget(b);if(Math.floor(b.ageSeconds/1800)>before)maintainBuild(b);}
export function offlineProgress(w,seconds){w.offlineBacklog=(w.offlineBacklog||0)+Math.max(0,seconds);seconds=Math.min(86400,w.offlineBacklog);w.offlineBacklog-=seconds;if(!seconds)return;for(const b of w.bots){age(b,seconds);const cycle=90+(b.seed%31);b.offlineRemainder=(b.offlineRemainder||0)+seconds;while(b.offlineRemainder>=cycle){b.offlineRemainder-=cycle;finishTask(b);}b.wait=0;b.task='outbound';b.goal={x:20+(b.seed%3),y:18+(b.seed%2)*2};b.targetId=null;b.route=null;}w.elapsedSeconds+=seconds;w.days=Math.floor(w.elapsedSeconds/86400);w.lastOfflineSeconds=seconds;}
function moveTo(b,goal,dt,context){b.moving=false;if(!goal)return false;const active=b.region===context.activeRegion&&!context.menu;const blocked=active?(x,y)=>context.blocked(x,y,'coast'):(x,y)=>x<2||y<2||x>62||y>62;const changed=!b.routeGoal||Math.hypot(b.routeGoal.x-goal.x,b.routeGoal.y-goal.y)>.6;if(changed||!b.route?.length){b.routeGoal={...goal};b.route=active?findPath(b,goal,blocked):[{...goal}];}while(b.route?.length&&Math.hypot(b.route[0].x-b.x,b.route[0].y-b.y)<.3)b.route.shift();const point=b.route?.[0];if(!point)return Math.hypot(b.x-goal.x,b.y-goal.y)<1.5;const dx=point.x-b.x,dy=point.y-b.y,d=Math.hypot(dx,dy),step=Math.min(d,dt*2.5);if(d&& !blocked(b.x+dx/d*step,b.y+dy/d*step)){b.x+=dx/d*step;b.y+=dy/d*step;b.moving=true;}return Math.hypot(b.x-goal.x,b.y-goal.y)<1.1;}
export function tickCitizens(w,dt,context){w.elapsedSeconds+=dt;w.days=Math.floor(w.elapsedSeconds/86400);const party=new Set(w.party);for(const b of w.bots){age(b,dt);b.attackAnim=Math.max(0,(b.attackAnim||0)-dt);b.cooldown=Math.max(0,(b.cooldown||0)-dt);b.skillCD=Math.max(0,(b.skillCD||0)-dt);b.potionCD=Math.max(0,(b.potionCD||0)-dt);if(party.has(b.id)){if(b.joinTravel>0){b.joinTravel=Math.max(0,b.joinTravel-dt);b.intent='Viajando para o grupo · '+Math.ceil(b.joinTravel)+'s';if(!b.joinTravel){b.region=context.player.region||0;b.zone=context.player.zone;b.x=context.player.x-3;b.y=context.player.y+2;}}continue;}b.zone='coast';const p=b.player,st=citizenStats(b);if(p.hp<=0){p.hp=st.hp;p.mp=st.mp;b.task='recover';b.wait=12;b.x=14;b.y=16;log(b,'Fui derrotado e retornei ao acampamento.');}
 if(b.task==='recover'){if(Math.hypot(b.x-13,b.y-14)>2){b.intent='Recuando para recuperar vida';moveTo(b,{x:13,y:14},dt,context);continue;}b.intent='Recuperando vida no acampamento';p.hp=Math.min(st.hp,p.hp+st.hp*.1*dt);p.mp=Math.min(st.mp,p.mp+st.mp*.15*dt);b.wait-=dt;b.moving=false;if(b.wait<=0){b.task='outbound';b.goal={x:20+(b.seed%3),y:18+(b.seed%2)*2};}continue;}
 p.mp=Math.min(st.mp,p.mp+st.mp*.03*dt);if(p.hp<st.hp*.3){if(p.pots.hp>0&&b.potionCD<=0){p.pots.hp--;b.potionCD=18;p.hp=Math.min(st.hp,p.hp+st.hp*.3);log(b,'Usei uma poção de vida.');}else{b.task='recover';b.wait=10;continue;}}
 const region=context.regions?.[b.region],min=region?.range?.[0]||1,active=b.region===context.activeRegion&&!context.menu,canHunt=p.level>=min;
 if(active&&canHunt&&p.hp>st.hp*.45){let target=context.enemies?.find(e=>e.id===b.targetId&&e.hp>0&&!e.boss&&!e.training);if(!target)target=context.enemies?.filter(e=>e.hp>0&&!e.boss&&!e.training&&e.level<=p.level+1).sort((a,c)=>Math.hypot(a.x-b.x,a.y-b.y)-Math.hypot(c.x-b.x,c.y-b.y))[0];if(target){b.targetId=target.id;b.intent='Caçando '+target.name+' · Nv'+target.level;const d=Math.hypot(target.x-b.x,target.y-b.y),range=Math.min(st.range,8);if(d>range*.85)moveTo(b,{x:target.x,y:target.y},dt,context);else{b.moving=false;if(b.cooldown<=0){const index=b.skillCD<=0?KITS[b.classId].findIndex((k,i)=>k.coef>0&&p.level>=SKILL_UNLOCK[i]&&p.mp>=k.cost&&k.range>=d):-1;const skill=index>=0?KITS[b.classId][index]:null;if(skill){p.mp-=skill.cost;b.skillCD=skill.cd;}const rng=rngFrom(b.seed+Math.floor(b.ageSeconds*10)),out=resolveStrike(st,b.classId,target,{index:index>=0?index:null,coefficient:skill?.coef||1,rng});b.cooldown=basicInterval(st);b.attackAnim=.55;context.onStrike(b,target,out,index>=0?index:null,false);if(target.hp<=0){finishTask(b,{hunt:true,enemyLevel:target.level});b.targetId=null;}else{const hurt=damage(target.atk,1,st.def,.05,1.5,rng,0,st.dr).value;p.hp-=hurt;}}}continue;}}
 b.targetId=null;if(b.task==='outbound'){b.intent=canHunt?'Procurando uma caça na região':'Levando suprimentos ao posto avançado';if(moveTo(b,b.goal,dt,context)){b.task='gather';b.wait=12+(b.seed%8);}}else if(b.task==='gather'){b.intent='Coletando suprimentos · '+Math.ceil(b.wait)+'s';b.moving=false;b.wait-=dt;if(b.wait<=0){b.task='return';b.goal={x:12+(b.seed%3),y:14};}}else if(b.task==='return'){b.intent='Voltando ao NPC para entregar a missão';if(moveTo(b,b.goal,dt,context)){finishTask(b);b.task='rest';b.wait=12;}}else{b.intent='Recebendo recompensa e preparando equipamento';b.moving=false;b.wait-=dt;if(b.wait<=0){b.task='outbound';b.goal={x:20+(b.seed%3),y:18+(b.seed%2)*2};}}
 }}
export function liveChatReply(b,message,w,regions){const text=String(message).toLowerCase(),name=regions?.[b.region]?.name||'região '+(b.region+1);if(/onde|mapa|local|regi[aã]o/.test(text))return 'Estou em '+name+', perto de '+Math.round(b.x)+', '+Math.round(b.y)+'. '+b.intent+'. Você pode vir até mim.';if(/fazendo|objetivo|evolu|n[ií]vel|exp/.test(text))return 'Comecei no nível 1. Agora estou no '+b.player.level+', com '+b.player.xp+' EXP, '+b.kills+' caças e '+b.quests+' entregas. '+b.intent+'.';if(/vem comigo|me siga|vamos juntos|quero.*grupo/.test(text)){if(!w.party.includes(b.id)){if(w.party.length>=4)return 'Seu grupo está cheio. Libere uma vaga e eu acompanho você.';w.party.push(b.id);b.joinTravel=15+Math.abs(b.region-(w.ownerRegion||0))*2;return 'Aceitei o convite! Estou viajando até você; devo chegar em '+b.joinTravel+' segundos.';}return 'Já estou no grupo. '+(b.joinTravel>0?'Ainda estou a caminho.':'Vou seguir você e ajudar no alvo.');}return null;}
